// Cloudflare Worker that relays MCP tool calls from Claude to the iOS app.
//
//   Claude  --HTTPS POST-->  /<token>/mcp     --+
//                                               |  Durable Object (one per token)
//   iOS app --WebSocket--->  /<token>/device  --+
//
// The token is a long random secret generated by the iOS app. Anyone holding it
// can reach the device, so it is treated like a password.

import { DurableObject } from "cloudflare:workers";
import { handleMcpRequest, textResult, type ToolResult } from "./mcp";
import { toolTimeoutMs } from "./tools";

export interface Env {
  RELAY: DurableObjectNamespace<DeviceRelay>;
}

const TOKEN_RE = /^[A-Za-z0-9_-]{32,128}$/;
const DEVICE_WAIT_MS = 15_000;

const NOT_CONNECTED =
  "The Claude Files Access app is not connected. Ask the user to open the app on their iPhone/iPad " +
  "(and keep it open, e.g. in Split View on iPad), then try again.";

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    const parts = url.pathname.split("/").filter(Boolean);

    if (parts.length === 0) {
      return new Response("Claude Files Access relay is running.\n", { headers: { "Content-Type": "text/plain" } });
    }
    if (parts.length !== 2 || !TOKEN_RE.test(parts[0]) || (parts[1] !== "mcp" && parts[1] !== "device")) {
      return new Response("Not found\n", { status: 404 });
    }

    const stub = env.RELAY.get(env.RELAY.idFromName(parts[0]));
    return stub.fetch(request);
  },
} satisfies ExportedHandler<Env>;

interface DeviceMessage {
  type: string;
  id?: string;
  result?: ToolResult;
}

interface PendingCall {
  resolve: (result: ToolResult) => void;
  timer: ReturnType<typeof setTimeout>;
}

export class DeviceRelay extends DurableObject<Env> {
  private pending = new Map<string, PendingCall>();
  private deviceWaiters: Array<(ws: WebSocket | null) => void> = [];

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    // Answer keepalive pings without waking the object from hibernation.
    ctx.setWebSocketAutoResponse(new WebSocketRequestResponsePair("ping", "pong"));
  }

  async fetch(request: Request): Promise<Response> {
    const path = new URL(request.url).pathname;
    if (path.endsWith("/device")) return this.acceptDevice(request);
    return handleMcpRequest(request, { callTool: (name, args) => this.callDevice(name, args) });
  }

  private acceptDevice(request: Request): Response {
    if (request.headers.get("Upgrade")?.toLowerCase() !== "websocket") {
      return new Response("Expected a WebSocket upgrade\n", { status: 426 });
    }
    // Only one device per token: a new connection replaces the old one.
    for (const old of this.ctx.getWebSockets()) {
      try {
        old.close(4000, "Replaced by a newer connection");
      } catch {
        // Already closed.
      }
    }

    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);
    this.ctx.acceptWebSocket(server);

    const waiters = this.deviceWaiters;
    this.deviceWaiters = [];
    for (const wake of waiters) wake(server);

    return new Response(null, { status: 101, webSocket: client });
  }

  private activeDevice(): WebSocket | null {
    const open = this.ctx.getWebSockets().filter((ws) => ws.readyState === WebSocket.OPEN);
    return open.length ? open[open.length - 1] : null;
  }

  private waitForDevice(ms: number): Promise<WebSocket | null> {
    return new Promise((resolve) => {
      const timer = setTimeout(() => {
        this.deviceWaiters = this.deviceWaiters.filter((w) => w !== wake);
        resolve(null);
      }, ms);
      const wake = (ws: WebSocket | null) => {
        clearTimeout(timer);
        resolve(ws);
      };
      this.deviceWaiters.push(wake);
    });
  }

  private async callDevice(name: string, args: Record<string, unknown>): Promise<ToolResult> {
    let ws = this.activeDevice();
    if (!ws && name !== "device_status") ws = await this.waitForDevice(DEVICE_WAIT_MS);
    if (!ws) {
      if (name === "device_status") {
        return textResult(JSON.stringify({ connected: false, hint: NOT_CONNECTED }, null, 2));
      }
      return textResult(NOT_CONNECTED, true);
    }

    const id = crypto.randomUUID();
    const timeoutMs = toolTimeoutMs(name);
    const device = ws;
    return new Promise<ToolResult>((resolve) => {
      const timer = setTimeout(() => {
        this.pending.delete(id);
        resolve(
          textResult(
            `The device did not answer within ${Math.round(timeoutMs / 1000)}s. ` +
              "The app may have been moved to the background; ask the user to bring it to the front and retry.",
            true,
          ),
        );
      }, timeoutMs);
      this.pending.set(id, { resolve, timer });
      try {
        device.send(JSON.stringify({ type: "call", id, tool: name, arguments: args }));
      } catch (err) {
        clearTimeout(timer);
        this.pending.delete(id);
        resolve(textResult(`Could not reach the device: ${err instanceof Error ? err.message : String(err)}`, true));
      }
    });
  }

  async webSocketMessage(_ws: WebSocket, message: string | ArrayBuffer): Promise<void> {
    if (typeof message !== "string") return;
    let msg: DeviceMessage;
    try {
      msg = JSON.parse(message) as DeviceMessage;
    } catch {
      return;
    }

    if (msg.type === "result" && typeof msg.id === "string") {
      const call = this.pending.get(msg.id);
      if (!call) return;
      this.pending.delete(msg.id);
      clearTimeout(call.timer);
      const result = msg.result;
      if (result && Array.isArray(result.content)) {
        call.resolve(result);
      } else {
        call.resolve(textResult("The device sent a malformed result.", true));
      }
    }
  }

  async webSocketClose(ws: WebSocket, code: number, reason: string): Promise<void> {
    try {
      ws.close(code === 1005 || code === 1006 ? 1000 : code, reason);
    } catch {
      // Already closed.
    }
    if (!this.activeDevice()) this.failPending("The device disconnected before answering.");
  }

  async webSocketError(): Promise<void> {
    if (!this.activeDevice()) this.failPending("The device connection failed before answering.");
  }

  private failPending(text: string): void {
    for (const [id, call] of this.pending) {
      clearTimeout(call.timer);
      call.resolve(textResult(text, true));
      this.pending.delete(id);
    }
  }
}
